'use strict';
(async()=>{
 const loading=document.getElementById('loading'),root=document.getElementById('library');
 if(location.protocol==='file:'){loading.textContent='素材来源审查需要 HTTP：在仓库运行 node scripts/serve.mjs，再打开 http://127.0.0.1:4173/prototype/experiments/global-assets.html。GitHub 交接文档同时提供截图。';return;}
 const read=async file=>{const r=await fetch('../../'+file);if(!r.ok)throw Error(file+' '+r.status);return r.json()};
 try{
  const [network,existing,cards,publicCards,library]=await Promise.all(['assets/global/network/manifest.json','assets/global/manifest.json','assets/cards/manifest.json','assets/cards/public/manifest.json','assets/global/library-manifest.json'].map(read));
  const find=file=>[...existing,...cards,...publicCards].find(x=>x.file===file);
  const brand=item=>({name:item.name,file:'assets/'+item.asset,sourcePage:item.sourcePage,note:item.note,background:item.background,padded:item.padded,...{license:find('assets/'+item.asset)?.license||'权利保留，见来源记录'}});
  const connectivity=NF_GLOBAL_BRANDS.filter(x=>['Club Sim','SMART'].includes(x.name)).map(brand);
  const accounts=NF_GLOBAL_BRANDS.filter(x=>library.accountsWallets.groups[0].brands.includes(x.name)).map(x=>({...brand(x),group:library.accountsWallets.groups[0].name}));
  const wallets=existing.filter(x=>library.accountsWallets.groups[1].brands.includes(x.name)).map(x=>({...x,group:library.accountsWallets.groups[1].name,note:'钱包快捷支付标识，仅作素材审查；不表示本站已接入支付或支持下方卡片。',status:'官方 acceptance mark · 原始 SVG',contrast:true}));
  for(const item of accounts)if(item.name==='Wise')item.note='金融科技服务 / 多币种资金与支付；不是传统银行。 '+item.note;
  const payment=library.paymentCards.items.map(role=>{const m=NF_CARD_MATERIALS.find(m=>m.id===role.id);return ({name:m.id==='cmb'?'招商银行 · 万事达人民币 IC 借记卡（普卡）':m.name,file:m.id==='starryblu'?'assets/cards/public/starryblu-card-sanitized.png':'assets/'+m.asset,original:'assets/'+m.asset,sourcePage:m.id==='cmb'?m.sourcePage:'../../assets/cards/SOURCES.md',note:m.id==='starryblu'?'直接使用已处理副本，印刷号码与姓名已在像素中替换；不是浏览器遮罩。':m.id==='cmb'?'四角白底已离线转为透明；原尺寸与卡面主体保留，不依赖浏览器遮罩。':m.privacy,license:find('assets/'+m.asset)?.license||'见卡面来源记录',status:m.id==='cmb'?'人民币借记卡，不是全币种信用卡。':'卡面用于视觉识别，不推断相同产品类型、发卡关系或开户条件。',card:true,visualRole:role.visualRole,productScope:role.productScope,scopeSource:role.officialSource,scopeVerifiedAt:role.verifiedAt});});
  const sections=[['01 / CONNECTIVITY','号码 / Connectivity','保留两个运营商品牌；SIM / eSIM、短信验证可以由后续通用数字结构表达。',connectivity],['02 / NETWORK','路径 / Network','已正式确认：Clash Verge Rev、FlClash、Shadowrocket、v2rayN。每份原图并排检查深色 / 暖白背景，不改色、不伪造透明底。',network.selected],[library.accountsWallets.label,library.accountsWallets.title,'账户资金服务：iFAST Global Bank、Wise、PayPal；钱包快捷支付：Apple Pay、Google Pay。'+library.accountsWallets.relationshipNote,[...accounts,...wallets]],[library.paymentCards.label,library.paymentCards.title,library.paymentCards.relationshipNote,payment]];
  const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text)n.textContent=text;return n};
  for(const [key,title,description,items] of sections){
   const section=el('section','asset-section');section.dataset.section=key;section.append(el('div','mono',key),el('h2','',title),el('p','section-note',description));const grid=el('div','asset-grid');
   for(const item of items){const row=el('article','material'+(item.card?' card':''));row.dataset.asset=item.file;if(item.category==='wallet'){row.classList.add('wallet-mark');row.dataset.name=item.name;}const art=el('div','art'+(item.background==='light'?' light':'')),img=new Image();img.src='../../'+item.file;img.alt=item.name;img.loading='eager';if(item.padded)img.className='padded';if(item.name==='Club Sim')img.style.maxWidth='105px';if(item.name==='SMART')img.style.maxWidth='149.5px';if(item.name==='iFAST Global Bank')img.style.width='150px';art.append(img);
    let visual=art;
    if(key.startsWith('02')||item.contrast){visual=el('div','contrast-pair');art.dataset.background=item.contrast?'white':'dark';if(item.contrast)art.classList.add('white');art.append(el('span','background-label',item.contrast?'纯白':'深色'));const light=el('div','art'+(item.contrast?'':' light'));light.dataset.background=item.contrast?'dark':'light';const copy=img.cloneNode();copy.addEventListener('error',()=>{copy.hidden=true;light.append(el('span','','图像未加载：'+item.name))});light.append(copy,el('span','background-label',item.contrast?'深色':'暖白'));visual.append(art,light);}
    const dimensions=el('p','dimensions','正在核对尺寸…');img.addEventListener('load',()=>{dimensions.textContent=(item.viewBox?'SVG · viewBox '+item.viewBox:img.naturalWidth+'×'+img.naturalHeight+' · '+item.file.split('.').pop().toUpperCase())+(item.hasAlpha===false?' · 原始应用底色 / 非透明':'')});img.addEventListener('error',()=>{img.hidden=true;dimensions.textContent='图片加载失败；名称与来源仍可阅读';});
    row.append(visual,el('h3','',item.name),dimensions,el('p','group',item.group||item.visualRole||''),el('p','status',item.status==='selected'?'正式展示'+(item.developer?' · 开发者：'+item.developer:''):item.status||''),el('p','',item.note||''),el('p','path',item.file),el('p','scope',item.productScope||''),el('p','',item.license));const links=el('div','links');for(const [label,href] of [['来源 ↗',item.sourcePage],['本地文件', '../../'+item.file],...(item.scopeSource?[['产品范围 / '+item.scopeVerifiedAt+' ↗',item.scopeSource]]:[]),...(item.usageRecord?[['标识规范','../../'+item.usageRecord]]:[]),...(item.licenseFile?[['上游许可','../../'+item.licenseFile]]:[])])if(href){const a=el('a','',label);a.href=href;if(href.startsWith('https://')){a.target='_blank';a.rel='noopener noreferrer'}links.append(a)}row.append(links);grid.append(row);
   }section.append(grid);if(key.startsWith('02')){section.append(el('p','concepts',network.concepts.join(' / ')),el('p','section-note','历史候选不参与正式展示：Clash Verge 原项目、V2Fly 文档标识。原文件及署名许可仅在 Network 来源记录与 manifest 的 historicalCandidates 中保留。'));}root.append(section);
  }
  await Promise.all([...root.querySelectorAll('img')].map(i=>i.decode()));loading.hidden=true;document.documentElement.dataset.ready='true';
 }catch(error){loading.textContent='素材记录读取失败：'+error.message;console.error(error)}
})();
